from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re
base='https://www.drivendata.org/competitions/'
root=Path('products/services/public-data-prize-trial')
raw=(root/'raw/drivendata-competitions.html').read_bytes()
class Index(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.current=None
        self.links={}
    def handle_starttag(self, tag, attrs):
        if tag=='a':
            self.current=(dict(attrs).get('href',''),[])
    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)
    def handle_endtag(self, tag):
        if tag!='a' or self.current is None:
            return
        href, parts=self.current
        self.current=None
        url=urlsplit(urljoin(base,href))
        if url.scheme!='https' or url.netloc!='www.drivendata.org' or not re.match(r'^/competitions/\d+(?:/|$)',url.path):
            return
        canonical=base.rstrip('/')+url.path.removeprefix('/competitions')
        label=' '.join(' '.join(parts).split())
        labels=self.links.setdefault(canonical,[])
        if label and label[:240] not in labels:
            labels.append(label[:240])
parser=Index()
parser.feed(raw.decode('utf-8',errors='replace'))
result={'source':base,'sha256':hashlib.sha256(raw).hexdigest(),'scope':'Index navigation only. Status, award, deadline and eligibility require official competition-specific evidence.','links':[{'url':url,'labels':labels} for url,labels in parser.links.items()]}
output=root/'director-index-navigation.json'
output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8'))==result
print(json.dumps({'links':len(result['links']),'output':str(output),'sha256':result['sha256']}))
